import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    response = requests.get(url, params=parameters, headers=HEADERS)
    if response.status_code != 200:
        raise Exception("Invalid URL or cannot access")
    data = response.json()
    if not data:
        raise Exception("Empty data")
    try:
        df = pd.DataFrame(data)
    except Exception:
        raise Exception("Invalid data")
    numeric_df = df.select_dtypes(include=['number'])
    if numeric_df.empty:
        raise Exception("No numerical data")
    corr_matrix = numeric_df.corr()
    fig, ax = plt.subplots()
    sns.heatmap(corr_matrix, annot=True, fmt=".2f", ax=ax)
    return df, ax

import pandas as pd
import os
import json
from collections import Counter
def task_func(json_dir_path, word_count):
    all_words = []
    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_dir_path, filename)
            with open(file_path, 'r') as f:
                data = json.load(f)
                if 'text' in data:
                    words = data['text'].lower().split()
                    all_words.extend(words)
    word_counter = Counter(all_words)
    return word_counter.most_common(word_count)

